  /* @import url('https://fonts.googleapis.com/css?family=Noto+Sans'); // 영문(알파벳 기반 806개 언어)
  @import url('https://fonts.googleapis.com/css?family=Noto+Sans+JP'); // 일문
  @import url('https://fonts.googleapis.com/css?family=Noto+Sans+KR'); // 한글, 중문, 일문, 라틴어, 그리스어
  @import url('https://fonts.googleapis.com/css?family=Noto+Sans+Thai'); // 태국어
  @import url('https://fonts.googleapis.com/css?family=Noto+Sans+Arabic'); // 아랍어 */

  button {
    outline: none;
  }

  html,
  body {

    margin: 0;
    padding: 0;
    height: 100%;
    width: 100%;
     ","

    // * {
    //   &::-webkit-scrollbar {
    //     width: .5em;
    //     height: .5em;
    //   }

    //   &::-webkit-scrollbar-thumb {
    //       background: #708090
    //   }

    //   &::-webkit-scrollbar-track {
    //       background: #b8c0c8;
    //   }
    // }
    [dir='rtl'] & {
      strong, span {
        display: inline-flex;
        align-items: center;
      }
    }
  }

  body {
    background-color: #171717;
    font-family: 'Noto Sans', 'Noto Sans JP', 'Noto Sans KR', 'Noto Sans Thai', 'Noto Sans Arabic', -apple-system, BlinkMacSystemFont, Roboto, Arial, "Microsoft YaHei", "Microsoft JhengHei", sans-serif;
    & * {
      //transition: all 0.2s ease;
      word-break: keep-all;
      word-wrap: break-word;
      /* letter-spacing: 0 !important; */
      font-family: 'Noto Sans', 'Noto Sans JP', 'Noto Sans KR', 'Noto Sans Thai', 'Noto Sans Arabic', -apple-system, BlinkMacSystemFont, Roboto, Arial, "Microsoft YaHei", "Microsoft JhengHei", sans-serif;
    }

    button, input, select, textarea { font-family: inherit; }
  }

  #root {
    ","

    color: #ffffff;
    a {
      text-decoration: none;
      // &:hover {
      //   @media (hover: hover), (-ms-high-contrast: active), (-ms-high-contrast: none) {
      //     text-decoration: underline;
      //   }
      // }
    }

    div {
      box-sizing: border-box;
    }

    button {
      cursor: pointer;
    }
  }

  textarea {
    font-size: 14px;
    font-weight: normal;
    line-height: 1.6;
    border: 1px solid transparent;
    color: rgba(255, 255, 255, 0.8);
    background: none;
    resize: none;
    font-weight: normal;
    &::placeholder {
      color: rgba(255, 255, 255, 0.3);
    }
    &:focus {
      outline: none;
      color: rgba(255, 255, 255, 1);
    }
    // &:hover {
    //   @media (hover: hover), (-ms-high-contrast: active), (-ms-high-contrast: none) {
    //     border-color: rgba(255, 255, 255, 0.3);
    //   }
    // }
  }
  input {
    font-weight: normal;
  }
  input[type='file'] {
    border: 0;
    outline: none;
    &:focus {
      border: 0;
      outline: none;
    }
  }
  img {
    max-width: 100%;
  }
  hr {
    &.topBar {
      border: 0;
      margin: 28px 0;
      height: 1px;
      background-color: rgba(255, 255, 255, 0.07);
    }
  }
  .topNavigation {
    @media only screen and (max-width: 959px) {
      button {
        top: 3px;
      }
    }  
  }

  // mobile cnb align
  @media only screen and (max-width: 959px) {
    #nc-cnb .ncc-bi {
      position: absolute;
      left: 50%;
      transform: translateX(-50%);
      margin-left: 0;
      white-space: nowrap;
    }
  }
  // safari cnb bug fix
  @media not all and (min-resolution: 0.001dpcm) {
    @media {
      #nc-cnb.is-sticky .ncc-header .ncc-gnb-wrap {
        display: block;
        @media only screen and (min-width: 960px) {
          display: none;
        }      
      }
    }
  }


  /* TW/JP/US CNB 우측 알림설정 버튼 노출 안함 */
  [data-country='TW'] #notiList .wrap_btns {display:none !important;}
